class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            transaction.Commit();
        });
    }
}

arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking change: EF Core 9 throws if Migrate() is called inside a
    // user-opened transaction. Migrations manage their own transactions.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            // Removed BeginTransaction — Migrate() handles transactions internally
            // and now throws InvalidOperationException if called inside one.
            db.Database.Migrate();
        });
    }
}

